def gen(rng):
    TAGS = ['us', 'uk', 'jp', 'de', 'fr', 'in', 'br', 'ca', 'au', 'cn']

    def ins(i, ts, tags):
        return 'INSERT %d %d %d %s' % (i, ts, len(tags), ' '.join(tags))

    def qry(t, lo, hi):
        return 'QUERY %s %d %d' % (t, lo, hi)

    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)

    def rand_small(nops, tags, tsmax, idmax):
        ids = rng.sample(range(1, idmax + 1), nops)
        ops = []
        for i in range(nops):
            if rng.random() < 0.55:
                k = rng.randint(1, min(3, len(tags)))
                ops.append(ins(ids[i], rng.randint(0, tsmax), rng.sample(tags, k)))
            else:
                lo = rng.randint(0, tsmax)
                hi = rng.randint(lo, tsmax)
                ops.append(qry(rng.choice(tags), lo, hi))
        ops.append(qry(rng.choice(tags), 0, tsmax))
        return ops

    tests = [
        fmt([ins(1, 0, ['a']), qry('a', 0, 0)]),
        fmt([qry('a', 0, 5)]),
        fmt([ins(5, 10, ['a']), ins(6, 20, ['a']), ins(7, 15, ['a']), qry('a', 10, 20), qry('a', 11, 19), qry('a', 21, 30)]),
        fmt([ins(30, 5, ['x']), ins(20, 5, ['x']), ins(10, 5, ['x']), qry('x', 5, 5), qry('x', 0, 4), qry('y', 0, 10)]),
        fmt([ins(10**9, 10**9, ['zz', 'yy']), ins(1, 0, ['zz']), qry('zz', 0, 10**9), qry('yy', 10**9, 10**9), qry('yy', 0, 10**9 - 1)]),
        fmt([qry('a', 0, 10), ins(1, 3, ['a', 'b']), qry('a', 0, 10), qry('b', 3, 3), ins(2, 3, ['b']), qry('b', 3, 3)]),
        fmt([ins(1, 100, ['us', 'uk', 'japan']), ins(2, 150, ['us']), ins(3, 120, ['uk', 'us']), qry('us', 100, 130), qry('japan', 0, 99), ins(4, 110, ['us']), qry('us', 100, 150)]),
    ]
    for nops in (3, 4, 5, 6, 7, 8, 9, 10):
        for _ in range(2):
            tests.append(fmt(rand_small(nops, TAGS[:rng.choice([2, 3, 4])], rng.choice([5, 20, 1000]), 10**9)))

    def big(n_ins, n_q, tags, tsmax, width, order, ins_first):
        ids = rng.sample(range(1, 10**9 + 1), n_ins)
        tss = [rng.randint(0, tsmax) for _ in range(n_ins)]
        if order == 'inc':
            tss.sort()
        elif order == 'dec':
            tss.sort(reverse=True)
        inserts = [ins(ids[i], tss[i], rng.sample(tags, rng.randint(1, min(3, len(tags))))) for i in range(n_ins)]
        queries = []
        for _ in range(n_q):
            lo = rng.randint(0, tsmax)
            queries.append(qry(rng.choice(tags), lo, min(tsmax, lo + rng.randint(0, width))))
        if ins_first:
            return inserts + queries
        ops = []
        qi = ii = 0
        while qi < n_q or ii < n_ins:
            if ii < n_ins and (qi >= n_q or rng.random() < n_ins / (n_ins + n_q)):
                ops.append(inserts[ii]); ii += 1
            else:
                ops.append(queries[qi]); qi += 1
        return ops

    tests.append(fmt(big(20000, 30000, TAGS, 10**9, 400000, 'rand', False)))
    tests.append(fmt(big(20000, 30000, TAGS, 10**9, 400000, 'rand', True)))
    tests.append(fmt(big(20000, 30000, ['a'], 20000 * 1000, 2500, 'inc', True)))
    tests.append(fmt(big(20000, 30000, ['a'], 20000 * 1000, 2500, 'dec', False)))
    many = ['t%d' % i for i in range(1000)]
    tests.append(fmt(big(20000, 30000, many, 10**9, 10**8, 'rand', False)))
    return tests

